        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "fitness": {
      "title": {
        "type": "string",
        "description": "运动卡片标题",
        "sampleValue": "运动"
      },
      "metricText": {
        "type": "string",
        "description": "一行展示的运动数字和单位",
        "sampleValue": "8,260步"
      },
      "caption": {
        "type": "string",
        "description": "主数字的简短说明",
        "sampleValue": "今日步数"
      },
      "statusLabel": {
        "type": "string",
        "description": "连接状态标签",
        "sampleValue": "设备状态"
      },
      "statusText": {
        "type": "string",
        "description": "当前连接状态文本",
        "sampleValue": "已连接"
      },
      "actionLabel": {
        "type": "string",
        "description": "跳转运动健康应用的按钮文本",
        "sampleValue": "去运动"
      }
    }
  },
  "assetCandidates": []
}

